-- Carga dos SKUs (código SAP e embalagem) de cada produto do catálogo, gerada
-- a partir da planilha Mapemento_Produtos_Pesquisa.xlsx. Separada da carga dos
-- produtos porque o app ainda não usa os SKUs. Reexecutar é seguro.
-- Os SKUs vêm compactados como 'código|embalagem|status' por produto.

insert into public.produto_skus (cod_sap, produto_id, descricao, embalagem, status)
select split_part(x, '|', 1), p.id, p.nome || ' - ' || split_part(x, '|', 2), split_part(x, '|', 2),
  case split_part(x, '|', 3) when '1' then 'Ativo' when '2' then 'Phase Out' when '3' then 'Inativo' when '4' then 'Exportação' when '5' then 'Granel' end
from (values
